// TH16 v1.00a approved aliases of identical TH18 type 0..43 slots (2026-11-07).
const TH16_RICE: int = 480;        // 源 etSprite type 8
const TH16_ARROWHEAD: int = 544;   // 源 etSprite type 12

// th16_s2_w05 — TH16 v1.00a st02 道中第二组 C01 编队。
// 源入口 st02.ecl.txt MainSub04:1030-1052；依赖 GirlC01/GirlC01_at/
// GirlA01/GirlA01_at/GirlBlueA01e/GirlRedA01e/MainSub01b/MainSub01c。
// 目标卡帧 = 120 帧外壳缓冲 + 源 MainSub04 帧。

const TIME_LIMIT: int = 2524;   // 120 + 2400 源窗口 + 4 启动余量
const OPENING_BUFFER: int = 120;

// 源 GirlC01_at 的 etEx(0,0,4,230,-999999,0.013,1.5707964)：固定方向向下
// 0.013 px/帧² 加速 230 帧后清除；出生 ANIM 已按口径省略，仅保留退位移
// （由发射器 sh_dist 表达）。
xformdef C01_ACCEL {
    @230 set_gravity(0fx, 0.013fx);
    set_gravity(0fx, 0fx);
}

// 源 GirlC01_at:358-410；f0 为源 %F0（MainSub04 创建前写入、子敌继承）。
sub girl_c01_at(f0: angle) {
    wait(60);
    // 源 0371 %C = %ANGLE_PLAYER：配置时点一次，不随每发重取。
    var c: angle = atan2($player_y - $self_y, $player_x - $self_x);
    var shots: int = 3;      // 源 diffI($E, 3, 3, 5, 7)
    var gap: int = 10;       // 源 !E 10 / !N 10 / !H 5 / !LO 3
    var tail: int = 120;     // 源轮末 wait: E 120 / N 60 / H 10 / LO 10
    if global(GVAR_RANK) == RANK_NORMAL {
        tail = 60;
    } else if global(GVAR_RANK) == RANK_HARD {
        shots = 5; gap = 5; tail = 10;
    } else if global(GVAR_RANK) >= RANK_LUNATIC {
        shots = 7; gap = 3; tail = 10;
    }

    // 源 etNew/etAim(0,3)/etSprite(0,12,13)/etCount(0,5,1) 配置一次；
    // 每发只改角/速（源 _572 覆盖 etAngle/etSpeed）。
    sh_reset(0);
    sh_sprite(0, TH16_ARROWHEAD, 13);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 5, 1);
    sh_angle(0, c, 0deg);
    sh_speed(0, 1fx, 0fx);
    sh_xform(0, C01_ACCEL);

    var a: fx = 1fx;         // 源 %A
    var b: fx = 0.2fx;       // 源 %B
    for round in 0..3 {      // 源 $D = 3
        a = 1fx;             // 源 _444: %A = 1.0
        for shot in 0..shots {
            sh_angle(0, c, 0deg);
            sh_speed(0, a, 0fx);
            sh_dist(0, -4fx * a);   // ANIM 出生退位移 position -= 4*velocity
            sh_fire(0);
            a = a + b;
            c = c + f0;
            wait(gap);
        }
        wait(tail);
    }
}

// 源 GirlC01:337-356。掉落/动画配置按公共口径省略；delete() 对应主任务自然结束。
async sub girl_c01(f0: angle) {
    set_invuln(65535);
    set_hurtbox(16fx);       // 源 setHurtbox(32,32) 普通圆 → r16
    set_hitbox(12fx);        // 源 setHitbox(24,24) → r12
    move_vel(0, 90deg, 2fx, EASE_LINEAR);
    move_vel(60, 90deg, 0.01fx, EASE_QUAD_IN);   // 源 mode1
    girl_c01_at(f0);
    move_vel(0, -90deg, 0fx, EASE_LINEAR);
    wait(90);
    move_vel(70, -90deg, 4fx, EASE_QUAD_IN);
    wait(700);
}

// 源 GirlA01:6-22。mirror=1 对应 enmCreateM 子镜像位：普通 moveVel 的方向
// 按水平镜像换算 angle -> 180deg - angle；发弹角不施加镜像。
sub girl_a01(mirror: int) {
    var a1: angle = 12288bam;    // 67.5deg，源 1.1780972
    var a2: angle = 4096bam;     // 22.5deg，源 0.3926991
    var a3: angle = -2048bam;    // -11.25deg，源 -0.19634955
    if mirror == 1 {
        a1 = 180deg - a1;
        a2 = 180deg - a2;
        a3 = 180deg - a3;
    }
    move_vel(0, a1, 2fx, EASE_LINEAR);
    wait(30);
    move_vel(60, a2, 1fx, EASE_LINEAR);    // 源 mode0
    wait(60);
    move_vel(60, a3, 2fx, EASE_LINEAR);
    loop { wait(1000); }
}

// 源 GirlA01_at:24-70（Normal/Hard/Lunatic 异步支线）。
async sub girl_a01_at() {
    var ways: int = 1;       // 源 etCount(0,[-1],1): 1,1,1,3
    var shots: int = 3;      // 源 diffI($A, 3, 3, 8, 12)
    var wmin: int = 40;      // 源 wait: E/N 40+RAND%140, H/L 30|20+RAND%20
    var wrange: int = 140;
    var speed: fx = 2fx;     // 源 etSpeed 首速: 2,2,3,3（单层只取首速）
    if global(GVAR_RANK) == RANK_HARD {
        shots = 8; wmin = 30; wrange = 20; speed = 3fx;
    } else if global(GVAR_RANK) >= RANK_LUNATIC {
        ways = 3; shots = 12; wmin = 20; wrange = 20; speed = 3fx;
    }

    // 源 etAngle(0, pi/2 + RANDF2*0.17453292, 0.6981317)：配置时抽一次 ±10°。
    var ru: int = rand(65536);
    var u: fx = (ru - 32768) as fx / 32768;
    var base: angle = 90deg + ((1820fx * u) as int) as angle;

    sh_reset(0);
    sh_sprite(0, TH16_RICE, 2);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_angle(0, base, 40deg);   // 源第二角 0.6981317
    sh_speed(0, speed, 0fx);
    sh_dist(0, -4fx * speed);
    for i in 0..shots {
        wait(wmin + rand(wrange));
        sh_fire(0);
    }
}

// 源 GirlBlueA01e:297-307 / GirlRedA01e:698-708；两者只差动画与掉落，行为相同。
async sub girl_a01e(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);       // 源 setHurtbox(24,24) → r12
    set_hitbox(8fx);         // 源 setHitbox(16,16) → r8
    if global(GVAR_RANK) >= RANK_NORMAL {
        spawn girl_a01_at();
    }
    girl_a01(mirror);
}

// 源 MainSub01b:930-944（x=192，enmCreateM，mirror=1）
// 与 MainSub01c:946-960（x=-192，enmCreate，mirror=0）。
async sub stream(x: fx, mirror: int) {
    for i in 0..5 {
        _ = spawn_enemy(x, -16fx, 100, 0, 0, 0, girl_a01e(mirror));
        wait(30);
        _ = spawn_enemy(x, -16fx, 100, 0, 0, 0, girl_a01e(mirror));
        wait(30);
    }
}

// 源 MainSub04:1030-1052；源入口 %F0 逐敌传入。
sub wave() {
    _ = spawn_enemy(96fx, -24fx, 700, 0, 0, 0, girl_c01(2deg));
    _ = spawn_enemy(-96fx, -24fx, 700, 0, 0, 0, girl_c01(-2deg));
    wait(120);
    spawn stream(192fx, 1);
    spawn stream(-192fx, 0);
    wait(180);
    _ = spawn_enemy(128fx, -24fx, 700, 0, 0, 0, girl_c01(-5deg));
    _ = spawn_enemy(-128fx, -24fx, 700, 0, 0, 0, girl_c01(5deg));
    wait(60);
    wait(180);
    _ = spawn_enemy(64fx, -24fx, 1500, 0, 0, 0, girl_c01(-5deg));
    _ = spawn_enemy(-64fx, -24fx, 1500, 0, 0, 0, girl_c01(5deg));
    wait(60);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wave();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
